//! Antigravity provider-specific authentication/usage bridge.
//!
//! ZeroClaw (`threetched`) owns the model catalog, provider routing and LLM
//! execution. This plugin retains only provider credential/status, safety
//! configuration and local usage integration; its `llm_plugin` field points
//! at the canonical native surface and does not define a parallel catalog.

use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, PluginCapabilities, StateDiff, StatePlugin};
