//! Typed method contracts and pure rules for `chat_response`: input bounds,
//! the content digest, the per-conversation turn hash chain, the single-use
//! generation admission, and the submit → lease → commit surface.
//!
//! Nothing here reads identity, stores rows or mints ids. The bridge mints
//! `conversation_id`/`turn_id`, verifies the caller, and commits; it builds
//! every record through these functions so one set of rules applies.
//!
//! # CallMethod contract (generation / claim / lease / commit)
//!
//! Claim is **not** a separate CallMethod. The coherent path is:
//! 1. **Submit** — `submit_turn` records the human message and opens a
//!    time-bounded response lease (`SubmitTurnOutput.expires_at`).
//! 2. **Read / generation admission** — `get_pending_turn_input` reads the
//!    exact designated input without mutation. After confirming automatic
//!    generation is admitted, `begin_generation` consumes that turn's one
//!    generation attempt before model work; it does not claim or return prompt.
//! 3. **Claim + commit** — `respond_to_user` / `request_clarification` /
//!    `cannot_perform` take the exclusive in-process claim on `turn_id`,
//!    then durable-commit or release (Drop returns the lease to pending
//!    until expiry). A late claim after `expires_at` is refused.

use super::chat_response::{
    ChatTurn, ConversationSummary, MessageType, RefusalCategory, ResponseContent,
};
use anyhow::{ensure, Context, Result};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

/// Domain tags inside the hashed canonical arrays.
pub const GENESIS_DOMAIN: &str = "opdbus.chat_response.genesis.v1";
pub const TURN_DOMAIN: &str = "opdbus.chat_response.turn.v1";

pub const MAX_TITLE_BYTES: usize = 256;
pub const MAX_MESSAGE_BYTES: usize = 1024 * 1024;
pub const MAX_QUESTION_BYTES: usize = 64 * 1024;
pub const MAX_CONTEXT_BYTES: usize = 64 * 1024;
pub const MAX_REASON_BYTES: usize = 64 * 1024;
pub const MAX_LIST_ITEMS: usize = 64;
pub const MAX_LIST_ITEM_BYTES: usize = 1024;
pub const MAX_ACTION_BYTES: usize = 256;
/// Upper bound before the sealed Canvas profile applies its own (smaller) limits.
pub const MAX_CANVAS_BYTES: usize = 1024 * 1024;
/// Serialized committed turn, content included.
pub const MAX_TURN_BYTES: usize = 4 * 1024 * 1024;
pub const MAX_CONVERSATION_BYTES: usize = 64 * 1024;
const MAX_IDENTITY_BYTES: usize = 512;
const MAX_TIMESTAMP_BYTES: usize = 64;

// ── Method inputs and outputs ────────────────────────────────────────────────

#[derive(Debug, Clone, Default, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct StartConversationInput {
    #[serde(default)]
    #[schemars(
        description = "Optional conversation title [PII]",
        extend("x-opdbus-private" = true)
    )]
    pub title: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct StartConversationOutput {
    /// Bridge-minted UUIDv7, bound to the caller's principal.
    pub conversation_id: String,
    /// RFC3339 start time (part of the conversation genesis hash).
    pub started_at: String,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum ResponseMode {
    Text,
    Application,
}

/// A new human message in an existing human-owned conversation. No caller
/// history, model override, responder identity or foreign context is accepted.
/// Opens a response lease; does not claim or commit the agent answer.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct SubmitTurnInput {
    pub conversation_id: String,
    #[schemars(description = "The human's new message [PII]", extend("x-opdbus-private" = true))]
    pub message: String,
    pub response_mode: ResponseMode,
}

impl SubmitTurnInput {
    /// Bounds for submit before the bridge opens the response lease.
    pub fn validate(&self) -> Result<()> {
        validate_uuid("conversation_id", &self.conversation_id)?;
        validate_content(&ResponseContent::HumanMessage {
            message: self.message.clone(),
        })?;
        Ok(())
    }
}

