90:fn sha256_file(path: &Path) -> Result<String> {
91:    let mut file = File::open(path).with_context(|| format!("open {}", path.display()))?;
92:    let mut hasher = Sha256::new();
93:    let mut buffer = [0u8; 64 * 1024];
94:    loop {
95:        let count = file.read(&mut buffer)?;
96:        if count == 0 {
97:            break;
98:        }
99:        hasher.update(&buffer[..count]);
100:    }
101:    Ok(format!("{:x}", hasher.finalize()))
102:}
103:
104:fn manifest_version(manifest: &Value, binary_hash: &str) -> Result<String> {
105:    ensure!(manifest["format"] == MANIFEST_FORMAT, "unsupported threetched manifest format");
106:    tched_fs::threetched_surface::validate_artifact_native_provenance(manifest)?;
107:    ensure!(manifest.pointer("/artifact/name").and_then(Value::as_str) == Some("threetched"), "manifest is not for the threetched executable");
108:    ensure!(manifest.pointer("/artifact/sha256").and_then(Value::as_str) == Some(binary_hash), "threetched executable differs from its manifest");
109:    let tag = manifest.pointer("/upstream/tag").and_then(Value::as_str)
110:        .context("threetched manifest has no upstream version")?;
111:    let version = tag.strip_prefix('v').filter(|value| !value.is_empty())
112:        .context("threetched manifest version must start with v")?;
113:    Ok(format!("zeroclaw {version}"))
114:}
