116:fn capture() -> Result<Captured> {
117:    let binary = super::tched_router_paths::binary()?;
118:    let manifest = super::tched_router_paths::manifest()?;
119:    let config_dir = super::tched_router_paths::config_dir()?;
120:    let (capture_binary, capture_manifest) = super::tched_router_paths::capture_paths()?;
121:    let manifest_sha256 = sha256_file(&capture_manifest)?;
122:    let descriptor: Value = serde_json::from_reader(File::open(&capture_manifest)?)?;
123:    let binary_sha256 = sha256_file(&capture_binary)?;
124:    let version = manifest_version(&descriptor, &binary_sha256)?;
125:    let bare_version = version.strip_prefix("zeroclaw ")
126:        .expect("manifest_version prefixes the bare version").to_owned();
127:    // Native schema startup writes defaults and traces. The capture owns a
128:    // disposable context; config-root defaults are explicitly relocated to the
129:    // sealed runtime root without reading or writing that runtime directory.
130:    let surface = ThreetchedSurface::capture_for_runtime(&capture_binary, &config_dir)?;
131:    ensure!(surface.binary_sha256() == binary_sha256, "threetched executable changed during capture");
132:    ensure!(surface.version() == Some(version.as_str()), "threetched version differs from its manifest");
133:    ensure!(sha256_file(&capture_manifest)? == manifest_sha256, "threetched manifest changed during capture");
134:    let state = ThreetchedState {
135:        binary: path_text(&binary)?,
136:        manifest: path_text(&manifest)?,
137:        config_dir: path_text(&config_dir)?,
138:        binary_sha256: surface.binary_sha256().to_owned(),
139:        manifest_sha256,
140:        surface: serde_json::to_value(surface.snapshot())?,
141:    };
142:    Ok(Captured { state, surface, version: bare_version })
143:}
