160:fn command_policy(method: &str) -> (String, String) {
161:    // Exact method bytes keep dotted/hyphenated CLI names distinct. This is a
162:    // policy identifier, not an inferred CLI type or a hardcoded method table.
163:    let key = format!("c{:x}", Sha256::digest(method.as_bytes()));
164:    (
