170:fn schema_from_capture(captured: &Captured) -> Result<PluginSchema> {
171:    let root = serde_json::to_value(schemars::schema_for!(ThreetchedState))?;
172:    let mut schema = super::schemars_adapter::plugin_schema_from_json(
173:        PLUGIN_NAME, VERSION, "Commands discovered from the pinned threetched binary", &root,
174:    );
175:    schema.category = "software".into();
176:    schema.display_name = Some("threetched".into());
177:    schema.tags = vec!["threetched".into(), "binary".into(), "immutable".into()];
178:    schema.immutable_paths = root["properties"].as_object().context("missing threetched descriptor fields")?
179:        .keys().map(|name| format!("/{name}")).collect();
180:    // Publish closed metadata fields; opaque discovery evidence is sealed in example.
181:    schema.public_state.paths = ["binary", "manifest", "config_dir", "binary_sha256", "manifest_sha256"]
182:        .map(|name| format!("/{name}")).into();
183:    let state = simd_json::serde::to_owned_value(&captured.state)?;
184:    super::schemars_adapter::apply_state_defaults(&mut schema, &state);
185:    schema.example = Some(state);
186:    for method in captured.surface.commands() {
187:        let input = captured.surface.input_schema(method)?;
188:        let output = captured.surface.output_schema(method)?;
189:        for contract in [&input, &output] {
190:            op_blob::descriptor::validate_json_schema_field_aliases(contract)
191:                .map_err(anyhow::Error::msg)
192:                .with_context(|| format!("threetched method {method} has ambiguous transport fields"))?;
193:        }
194:        let (capability, subid) = command_policy(method);
195:        schema.capabilities.insert(capability.clone(), CapabilityDecl {
196:            id: capability.clone(),
197:            description: format!("Execute threetched CLI command {method} in the sealed runtime context."),
198:        });
199:        schema.methods.insert(method.to_owned(), MethodDecl {
200:            name: method.to_owned(),
201:            args: simd_json::serde::to_owned_value(input)?,
202:            returns: Some(simd_json::serde::to_owned_value(output)?),
203:            side_effect: SideEffect::Mutation,
204:            idempotent: false,
205:            required_capability: Some(capability),
206:            subid,
207:        });
208:    }
209:    ensure!(!schema.methods.is_empty(), "threetched binary supplied no callable commands");
210:    Ok(schema)
211:}
