            "2026-09-28T10:00:00.000Z",
        )
        .is_err());

        let pending = PendingTurnInfo {
            turn_id: turn_id.clone(),
            conversation_id: conversation_id.clone(),
            turn_index: 1,
            owner_key: "ab".repeat(32),
            owner_principal_id: PRINCIPAL.into(),
            opened_at: "2026-09-28T10:00:00.000Z".into(),
            expires_at: "2026-09-28T10:00:30.000Z".into(),
