        validate_pending_turn_info(&pending).unwrap();
        let mut inverted = pending.clone();
        inverted.expires_at = inverted.opened_at.clone();
        assert!(validate_pending_turn_info(&inverted).is_err());

        GetPendingTurnInput {
            turn_id: turn_id.clone(),
        }
        .validate()
        .unwrap();
        assert!(GetPendingTurnInput {
            turn_id: "bad".into(),
        }
        .validate()
        .is_err());

        let input_out = GetPendingTurnInputOutput {
            turn_id,
            expires_at: "2026-09-28T10:00:30.000Z".into(),
            prompt: "what is up?".into(),
            context: PendingTurnInputContext {
                conversation_id,
                turn_index: 1,
                prompt_turn_hash: "cd".repeat(32),
                prior_turns: vec![],
                prior_turns_truncated: false,
            },
            generation: None,
        };
        validate_pending_turn_input_output(&input_out).unwrap();
    }
