        }
        assert_eq!(
            schema.methods["submit_turn"].required_capability.as_deref(),
            Some(SUBMIT_CAPABILITY)
        );
        for method in [
            "start_conversation",
            "get_turn_response",
            "list_conversations",
            "get_conversation",
            "get_doorbell",
        ] {
            assert_eq!(
                schema.methods[method].required_capability.as_deref(),
                Some(READ_CAPABILITY)
            );
        }
        assert!(schema.capabilities.contains_key(SUBMIT_CAPABILITY));
        let doorbell_input =
            serde_json::to_value(&schema.methods["get_doorbell"].args).unwrap();
