        for field in ["conversation_id", "turn_id", "turn_index", "expires_at"] {
            assert!(
                submit_out.to_string().contains(field),
                "submit_turn returns {field}"
            );
        }
        let pending = serde_json::to_value(schema.methods["list_pending_turns"].returns.as_ref())
