//! Binary-discovered threetched methods owned by one sealed plugin contract.
//!
//! The binary supplies command words, flags and token schemas. This plugin owns
//! admission policy; help text cannot establish that a command is read-only.
//! opblob is the sole sealer. Filesystem and transport consumers project its
//! sealed declarations and dispatch through the existing MutationEngine gate.

use std::path::PathBuf;
…
use tched_fs::threetched_surface::ThreetchedSurface;
// Paths to the threetched binary and manifest. Defaults mirror the
// deployed runit service; overrides use THREETCHED_BIN,
// THREETCHED_MANIFEST and TCHED_ROUTER_CONFIG_DIR.
pub const DEFAULT_BINARY: &str = "/usr/local/libexec/op-dbus/threetched/threetched";
pub const DEFAULT_CONFIG_DIR: &str = "/var/lib/tched-router";
pub const DEFAULT_MANIFEST: &str = "/usr/share/op-dbus/threetched-manifests/tched-router.json";

fn absolute_env_path(name: &str, default: &str) -> Result<PathBuf> { … }

pub(crate) fn binary() -> Result<PathBuf> {
    absolute_env_path("THREETCHED_BIN", DEFAULT_BINARY)
}

pub(crate) fn config_dir() -> Result<PathBuf> {
    absolute_env_path("TCHED_ROUTER_CONFIG_DIR", DEFAULT_CONFIG_DIR)
}

pub(crate) fn manifest() -> Result<PathBuf> {
    absolute_env_path("THREETCHED_MANIFEST", DEFAULT_MANIFEST)
}

/// Select the binary and provenance manifest used only to capture the sealed
/// CLI contract. Runtime dispatch continues to use [`binary`] and [`manifest`].
/// Build/seal invocations may point these selectors at a not-yet-installed
/// candidate, but must supply the pair together so provenance cannot drift.
pub(crate) fn capture_paths() -> Result<(PathBuf, PathBuf)> { … }

pub const PLUGIN_NAME: &str = "threetched";
const VERSION: &str = "1.0.0";
const MANIFEST_FORMAT: &str = "opdbus.threetched.v2";

/// Immutable discovery evidence, never a copy of the running configuration.
/// Capture selectors are build/seal inputs; these paths select the installed
/// runtime and stay identical when the candidate is staged into a release.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct ThreetchedState { … }

struct Captured { … }

static CAPTURED: OnceLock<std::result::Result<Captured, String>> = OnceLock::new();

/// Explicit authoring entry point for opblob and generated bridge contracts.
/// Each opblob command is a new process: every seal captures fresh bytes, shared
/// by all consumers in that invocation. Runtime never initializes this cache.
pub fn prepare_schema_capture() -> Result<()> { … }

pub(crate) fn is_schema_capture() -> bool {
    CAPTURED.get().is_some()
}

fn captured() -> Result<&'static Captured> { … }

pub(crate) fn sealed_schema(plugin_id: &str) -> Result<PluginSchema> { … }

pub(crate) fn sealed_state(plugin_id: &str) -> Result<OwnedValue> { … }

pub(crate) fn capture_state() -> Result<&'static ThreetchedState> {
    Ok(&captured()?.state)
}

fn path_text(path: &Path) -> Result<String> {
    Ok(path.to_str().context("threetched path is not UTF-8")?.to_owned())
}

fn sha256_file(path: &Path) -> Result<String> { … }

fn manifest_version(manifest: &Value, binary_hash: &str) -> Result<String> { … }

fn capture() -> Result<Captured> { … }

/// The pinned binary surface captured once at seal.
pub(crate) fn surface() -> Result<&'static ThreetchedSurface> {
    Ok(&captured()?.surface)
}

/// The threetched `config schema` document from the same pinned capture.
pub(crate) fn config_schema() -> Result<&'static Value> {
    Ok(captured()?.surface.schema_json())
}

/// The bare upstream version (e.g. "0.8.4") verified against the manifest.
pub(crate) fn binary_version() -> Result<&'static str> {
    Ok(captured()?.version.as_str())
}

fn command_policy(method: &str) -> (String, String) { … }

fn schema_from_capture(captured: &Captured) -> Result<PluginSchema> { … }

pub fn threetched_schema() -> PluginSchema { … }

pub fn state_value() -> Result<OwnedValue> { … }

#[derive(Default)]
pub struct ThreetchedPlugin;

#[async_trait]
impl StatePlugin for ThreetchedPlugin { … }


inventory::submit! {
    crate::default_registry::PluginReg::new(PLUGIN_NAME, |_ctx| Arc::new(ThreetchedPlugin))
}

