140:fn sha256_file(path: &Path) -> Result<String> {
141:    let mut file = File::open(path).with_context(|| format!("open {}", path.display()))?;
142:    let mut hasher = Sha256::new();
143:    let mut buffer = [0u8; 64 * 1024];
144:    loop {
145:        let count = file.read(&mut buffer)?;
146:        if count == 0 {
147:            break;
148:        }
149:        hasher.update(&buffer[..count]);
150:    }
151:    Ok(format!("{:x}", hasher.finalize()))
152:}
