154:fn manifest_version(manifest: &Value, binary_hash: &str) -> Result<String> {
155:    ensure!(manifest["format"] == MANIFEST_FORMAT, "unsupported threetched manifest format");
156:    tched_fs::threetched_surface::validate_artifact_native_provenance(manifest)?;
157:    ensure!(manifest.pointer("/artifact/name").and_then(Value::as_str) == Some("threetched"), "manifest is not for the threetched executable");
158:    ensure!(manifest.pointer("/artifact/sha256").and_then(Value::as_str) == Some(binary_hash), "threetched executable differs from its manifest");
159:    let tag = manifest.pointer("/upstream/tag").and_then(Value::as_str)
160:        .context("threetched manifest has no upstream version")?;
161:    let version = tag.strip_prefix('v').filter(|value| !value.is_empty())
162:        .context("threetched manifest version must start with v")?;
163:    Ok(format!("zeroclaw {version}"))
164:}
