166:fn capture() -> Result<Captured> {
167:    let binary = super::tched_router_paths::binary()?;
168:    let manifest = super::tched_router_paths::manifest()?;
169:    let config_dir = super::tched_router_paths::config_dir()?;
170:    let (capture_binary, capture_manifest) = super::tched_router_paths::capture_paths()?;
171:    let manifest_sha256 = sha256_file(&capture_manifest)?;
172:    let descriptor: Value = serde_json::from_reader(File::open(&capture_manifest)?)?;
173:    let binary_sha256 = sha256_file(&capture_binary)?;
174:    let version = manifest_version(&descriptor, &binary_sha256)?;
175:    let bare_version = version.strip_prefix("zeroclaw ")
176:        .expect("manifest_version prefixes the bare version").to_owned();
177:    // Native schema startup writes defaults and traces. The capture owns a
178:    // disposable context; config-root defaults are explicitly relocated to the
179:    // sealed runtime root without reading or writing that runtime directory.
180:    let surface = ThreetchedSurface::capture_for_runtime(&capture_binary, &config_dir)?;
181:    ensure!(surface.binary_sha256() == binary_sha256, "threetched executable changed during capture");
182:    ensure!(surface.version() == Some(version.as_str()), "threetched version differs from its manifest");
183:    ensure!(sha256_file(&capture_manifest)? == manifest_sha256, "threetched manifest changed during capture");
184:    let state = ThreetchedState {
185:        binary: path_text(&binary)?,
186:        manifest: path_text(&manifest)?,
187:        config_dir: path_text(&config_dir)?,
188:        binary_sha256: surface.binary_sha256().to_owned(),
189:        manifest_sha256,
190:        surface: serde_json::to_value(surface.snapshot())?,
191:    };
192:    Ok(Captured { state, surface, version: bare_version })
193:}
