210:fn command_policy(method: &str) -> (String, String) {
211:    // Exact method bytes keep dotted/hyphenated CLI names distinct. This is a
212:    // policy identifier, not an inferred CLI type or a hardcoded method table.
213:    let key = format!("c{:x}", Sha256::digest(method.as_bytes()));
214:    (
215:        format!("cap.software.threetched.call.{key}@v1"),
216:        format!("mut.software.threetched.call.{key}@v1"),
217:    )
218:}
