220:fn schema_from_capture(captured: &Captured) -> Result<PluginSchema> {
221:    let root = serde_json::to_value(schemars::schema_for!(ThreetchedState))?;
222:    let mut schema = super::schemars_adapter::plugin_schema_from_json(
223:        PLUGIN_NAME, VERSION, "Commands discovered from the pinned threetched binary", &root,
224:    );
225:    schema.category = "software".into();
226:    schema.display_name = Some("threetched".into());
227:    schema.tags = vec!["threetched".into(), "binary".into(), "immutable".into()];
228:    schema.immutable_paths = root["properties"].as_object().context("missing threetched descriptor fields")?
229:        .keys().map(|name| format!("/{name}")).collect();
230:    // Publish closed metadata fields; opaque discovery evidence is sealed in example.
231:    schema.public_state.paths = ["binary", "manifest", "config_dir", "binary_sha256", "manifest_sha256"]
232:        .map(|name| format!("/{name}")).into();
233:    let state = simd_json::serde::to_owned_value(&captured.state)?;
234:    super::schemars_adapter::apply_state_defaults(&mut schema, &state);
235:    schema.example = Some(state);
236:    for method in captured.surface.commands() {
237:        let input = captured.surface.input_schema(method)?;
238:        let output = captured.surface.output_schema(method)?;
239:        for contract in [&input, &output] {
240:            op_blob::descriptor::validate_json_schema_field_aliases(contract)
241:                .map_err(anyhow::Error::msg)
242:                .with_context(|| format!("threetched method {method} has ambiguous transport fields"))?;
243:        }
244:        let (capability, subid) = command_policy(method);
245:        schema.capabilities.insert(capability.clone(), CapabilityDecl {
246:            id: capability.clone(),
247:            description: format!("Execute threetched CLI command {method} in the sealed runtime context."),
248:        });
249:        schema.methods.insert(method.to_owned(), MethodDecl {
250:            name: method.to_owned(),
251:            args: simd_json::serde::to_owned_value(input)?,
252:            returns: Some(simd_json::serde::to_owned_value(output)?),
253:            side_effect: SideEffect::Mutation,
254:            idempotent: false,
255:            required_capability: Some(capability),
256:            subid,
257:        });
258:    }
259:    ensure!(!schema.methods.is_empty(), "threetched binary supplied no callable commands");
260:    Ok(schema)
261:}
